Lemma g3_call : forall t0' t1' t2' t3' t4' t5' t6' s2' s3' s4' s5' s6' (F' : bvmap 5 word) fc (m : word -> option byte) (Wm W Wp s Ks : Z) (bs : list byte) lj j8,
  frm0 fc ->
  stk rsegs m (GSP - 128) (GSP - 80) ->
  rw_cells rsegs m (GSP - 80) [C8 (Z_to_bv 64 kp); CB 8 j8; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
  munch G3_W m0 m -> wmono rsegs m0 m -> mem_inv rsegs m ->
  u8arr rsegs m buf bs -> length bs = 22%nat -> rw_cells rsegs m lenp [C4 lj] -> rw_cells rsegs m kp [C4 (Z_to_bv 64 Ks)] ->
  (56 <= s <= 59)%Z -> (1 <= Wm <= W)%Z -> (W <= Wp <= 2 ^ 64 - 2)%Z -> (2 ^ 62 <= Wp + 1)%Z -> (-325 <= Ks <= 307)%Z ->
  evt rsegs g3_post (MS (mkR (Z_to_bv 64 0x42250) (Z_to_bv 64 (GSP - 80)) gp tp t0' t1' t2' (Z_to_bv 64 buf) (Z_to_bv 64 lenp)
                             (Z_to_bv 64 Wm) (Z_to_bv 64 (2 ^ 32 - s)) (Z_to_bv 64 W) (Z_to_bv 64 (2 ^ 32 - s)) (Z_to_bv 64 Wp) (Z_to_bv 64 (2 ^ 32 - s))
